package com.hbm.client.soldering;
import com.hbm.machine.soldering.*;import mezz.jei.api.*;import mezz.jei.api.gui.builder.IRecipeLayoutBuilder;import mezz.jei.api.gui.drawable.IDrawable;import mezz.jei.api.gui.ingredient.IRecipeSlotsView;import mezz.jei.api.helpers.IGuiHelper;import mezz.jei.api.recipe.*;import mezz.jei.api.recipe.category.IRecipeCategory;import mezz.jei.api.registration.*;import net.minecraft.client.Minecraft;import net.minecraft.client.gui.GuiGraphics;import net.minecraft.network.chat.Component;import net.minecraft.resources.ResourceLocation;import net.minecraft.world.item.ItemStack;
@JeiPlugin public final class SolderingJeiPlugin implements IModPlugin {
 static final RecipeType<SolderingRecipe> TYPE=RecipeType.create("hbm","soldering",SolderingRecipe.class);
 @Override public ResourceLocation getPluginUid(){return SolderingContent.id("soldering_jei");}@Override public void registerCategories(IRecipeCategoryRegistration event){event.addRecipeCategories(new Category(event.getJeiHelpers().getGuiHelper()));}@Override public void registerRecipes(IRecipeRegistration event){var level=Minecraft.getInstance().level;if(level!=null)event.addRecipes(TYPE,SolderingRecipes.recipes(level.getRecipeManager()));}@Override public void registerRecipeCatalysts(IRecipeCatalystRegistration event){event.addRecipeCatalysts(TYPE,SolderingContent.ITEM.get());}@Override public void registerGuiHandlers(IGuiHandlerRegistration event){event.addRecipeClickArea(SolderingScreen.class,67,17,32,14,TYPE);}
 private static final class Category implements IRecipeCategory<SolderingRecipe>{private final IDrawable background,icon;Category(IGuiHelper helper){background=helper.createBlankDrawable(166,65);icon=helper.createDrawableItemStack(new ItemStack(SolderingContent.ITEM.get()));}@Override public RecipeType<SolderingRecipe> getRecipeType(){return TYPE;}@Override public Component getTitle(){return Component.translatable("jei.hbm.soldering");}@Override public IDrawable getBackground(){return background;}@Override public IDrawable getIcon(){return icon;}@Override public void setRecipe(IRecipeLayoutBuilder builder,SolderingRecipe recipe,IFocusGroup focus){var inputs=SolderingViews.inputs(recipe);var positions=SolderingViews.positions(recipe);for(int i=0;i<inputs.size();i++)builder.addSlot(RecipeIngredientRole.INPUT,positions[i][0],positions[i][1]).addItemStacks(inputs.get(i));builder.addSlot(RecipeIngredientRole.OUTPUT,102,24).addItemStack(recipe.output());builder.addSlot(RecipeIngredientRole.CATALYST,75,31).addItemStack(new ItemStack(SolderingContent.ITEM.get()));}@Override public void draw(SolderingRecipe recipe,IRecipeSlotsView slots,GuiGraphics graphics,double x,double y){SolderingViews.draw(recipe,graphics,0,0);}}
}
